import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    ys = [0] * n
    for i in range(n):
        x, y = data[1 + 2 * i: 3 + 2 * i]
        ys[x - 1] = y

    allmask = (1 << n) - 1
    inv_neighbors = []
    for i in range(n):
        mask = 0
        for j in range(n):
            if (i - j) * (ys[i] - ys[j]) < 0:
                mask |= 1 << j
        inv_neighbors.append(mask)

    # Selected balls must be pairwise incomparable. For each such selection,
    # the final set is the selection together with all balls incomparable to it.
    outcomes = set()

    def enumerate_selections(start, previous_y, selected, common_neighbors):
        outcomes.add(selected | common_neighbors)
        for i in range(start, n):
            if ys[i] < previous_y:
                enumerate_selections(
                    i + 1, ys[i], selected | (1 << i),
                    common_neighbors & inv_neighbors[i]
                )

    enumerate_selections(0, n + 1, 0, allmask)
    print(len(outcomes) % 998244353)

solve()

