import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    factorizations = []
    primes = set()
    for value in a:
        factors = {}
        q = value
        p = 2
        while p * p <= q:
            while q % p == 0:
                factors[p] = factors.get(p, 0) + 1
                q //= p
            p += 1
        if q > 1:
            factors[q] = factors.get(q, 0) + 1
        factorizations.append(factors)
        primes.update(factors)

    answer = 1
    for prime in primes:
        steps = [f.get(prime, 0) for f in factorizations]
        total = sum(steps)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * prime % MOD

        # u: walks which have not touched height 0; t: walks which have.
        u = [0] * (total + 1)
        t = [0] * (total + 1)
        t[0] = 1
        for h in range(1, total + 1):
            u[h] = powers[h]

        for d in steps:
            nu = [0] * (total + 1)
            nt = [0] * (total + 1)
            for h in range(total + 1):
                if d == 0:
                    destinations = (h,)
                else:
                    destinations = (h + d, h - d)
                if u[h]:
                    for nh in destinations:
                        if 0 <= nh <= total:
                            if nh == 0:
                                nt[nh] = (nt[nh] + u[h] * powers[nh]) % MOD
                            else:
                                nu[nh] = (nu[nh] + u[h] * powers[nh]) % MOD
                if t[h]:
                    for nh in destinations:
                        if 0 <= nh <= total:
                            nt[nh] = (nt[nh] + t[h] * powers[nh]) % MOD
            u, t = nu, nt

        answer = answer * (sum(t) % MOD) % MOD

    print(answer)

solve()

