def mul(a,b,m):
 c=[0]*m
 for i,x in enumerate(a):
  if x:
   for j,y in enumerate(b):
    if y:c[(i+j)%m]=(c[(i+j)%m]+x*y)%MOD
 return c

def power(a,e,m):
 r=[0]*m;r[0]=1
 while e:
  if e&1:r=mul(r,a,m)
  a=mul(a,a,m);e>>=1
