def fwht(a):
 n=len(a);h=1
 while h<n:
  for i in range(0,n,2*h):
   x=a[i:i+h];y=a[i+h:i+2*h]
   a[i:i+h]=[u+v for u,v in zip(x,y)]
   a[i+h:i+2*h]=[u-v for u,v in zip(x,y)]
  h*=2

