import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,q=data[0],data[1]
    parent=list(range(n)); sz=[1]*n; lo=list(range(n)); hi=list(range(n)); color=list(range(1,n+1)); cnt=[0]*(n+1)
    for i in range(1,n+1): cnt[i]=1
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def merge(a,b):
        a=find(a); b=find(b)
        if a==b: return a
        if sz[a]<sz[b]: a,b=b,a
        parent[b]=a
        sz[a]+=sz[b]
        lo[a]=min(lo[a],lo[b]); hi[a]=max(hi[a],hi[b])
        return a
    out=[]; idx=2
    for _ in range(q):
        typ=data[idx]; idx+=1
        if typ==1:
            x=data[idx]-1; c=data[idx+1]; idx+=2
            r=find(x); old=color[r]
            if old!=c:
                cnt[old]-=sz[r]; cnt[c]+=sz[r]
                color[r]=c
                if lo[r]>0:
                    l=find(lo[r]-1)
                    if color[l]==c: r=merge(r,l)
                if hi[r]<n-1:
                    rr=find(hi[r]+1)
                    if color[rr]==c: r=merge(r,rr)
        else:
            c=data[idx]; idx+=1
            out.append(str(cnt[c]))
    sys.stdout.write('\n'.join(out))
