from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, idx))

        best = second = 0
        count = 0
        best_id = -1
        gains = [0] * m
        total = 0

        for r in range(1, n + 1):
            for x, idx in at[r]:
                if x > best:
                    second = best
                    best = x
                    count = 1
                    best_id = idx
                elif x == best:
                    count += 1
                    second = best
                elif x > second:
                    second = x

            total += r - best
            if count == 1:
                gains[best_id] += best - second

        return total + max(gains)

