        for r in range(1, n + 1):
            for x, idx in at[r]:
                if x > best:
                    second = best
                    best = x
                    count = 1
                    best_id = idx
                elif x == best:
                    count += 1
                    second = best
                elif x > second:
                    second = x

            total += r - best
            if count == 1:
                gains[best_id] += best - second

        return total + max(gains)

