import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, X = data[:2]
    machines = []
    pos = 2
    for _ in range(N):
        A, P, B, Q = data[pos:pos + 4]
        pos += 4
        g = math.gcd(A, B)
        machines.append((A, P, B, Q, B // g, A // g))

    def feasible(k):
        total = 0
        for A, P, B, Q, m, n in machines:
            best = ((k + A - 1) // A) * P
            for x in range(m):
                y = max(0, (k - A * x + B - 1) // B)
                cost = x * P + y * Q
                if cost < best:
                    best = cost
            for y in range(n):
                x = max(0, (k - B * y + A - 1) // A)
                cost = y * Q + x * P
                if cost < best:
                    best = cost
            total += best
            if total > X:
                return False
        return True

    lo, hi = 0, X * 100 + 1
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == '__main__':
    main()

