class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        nbits = len(s)

        # depth[x] is the number of popcount operations needed to reach 1.
        depth = [0] * (nbits + 1)
        for x in range(2, nbits + 1):
            depth[x] = 1 + depth[x.bit_count()]

        # A number with j set bits takes one operation to become j, then
        # depth[j] more operations to become 1.
        valid = [False] * (nbits + 1)
        for j in range(1, nbits + 1):
            valid[j] = depth[j] <= k - 1

        # Binomial coefficients, modulo MOD.
        choose = [[0] * (nbits + 1) for _ in range(nbits + 1)]
        choose[0][0] = 1
        for a in range(1, nbits + 1):
            choose[a][0] = choose[a][a] = 1
            for b in range(1, a):
                choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD

        ans = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = nbits - i - 1
                for weight in range(1, nbits + 1):
                    if valid[weight] and weight >= prefix_ones:
                        need = weight - prefix_ones
                        if need <= remaining:
                            ans += choose[remaining][need]
                prefix_ones += 1

        return ans % MOD

