import sys

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    it=iter(data); n=next(it); m=next(it); q=next(it)
    people=[]
    for _ in range(m):
        s=next(it)-1;t=next(it)-1
        people.append((s,t))
    queries=[(next(it)-1,next(it)-1) for _ in range(q)]
    out=[]
    for L,R in queries:
        par=list(range(n))
        def find(x):
            while par[x]!=x:
                par[x]=par[par[x]];x=par[x]
            return x
        for s,t in people[L:R+1]:
            a,b=sorted((s,t));x=find(a);y=find(b)
            if x!=y:par[x]=y
        edges=[]
        for s,t in people[L:R+1]:
            a,b=sorted((s,t)); ra=find(a); rb=find(b)
            for z in range(a+1,b):
                rz=find(z)
                if s<t: edges.append((ra,rz))
                else: edges.append((rz,ra))
        roots={find(i) for i in range(n)}
        adj={x:[] for x in roots}; indeg={x:0 for x in roots}
        for u,v in edges:
            if u==v: break
            adj[u].append(v);indeg[v]+=1
        else:
            stack=[x for x in roots if indeg[x]==0]; seen=0
            while stack:
                u=stack.pop();seen+=1
                for v in adj[u]:
                    indeg[v]-=1
                    if indeg[v]==0:stack.append(v)
            out.append('Yes' if seen==len(roots) else 'No')
            continue
        out.append('No')
    print('\n'.join(out))

if __name__=='__main__':solve()

