from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    g = [x.decode() for x in data[1:1 + n]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    dist = [[-1] * n for _ in range(n)]
    q = deque()
    # A palindrome can have an empty center.
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))
    # Or it can consist of one edge.
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                q.append((i, j))

    # Add matching letters to both ends of each known palindrome.
    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2
        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            for x in left:
                row = dist[x]
                for y in right:
                    if row[y] == -1:
                        row[y] = nd
                        q.append((x, y))

    print('\n'.join(' '.join(map(str, row)) for row in dist))

