import math

N = int(input())
ans = None

# Let d = x - y. Then N = d * (3y^2 + 3dy + d^2), so d^3 <= N.
for d in range(1, 1_000_001):
    if d * d * d > N:
        break
    if N % d:
        continue

    q = N // d
    discriminant = 12 * q - 3 * d * d
    if discriminant < 0:
        continue

    root = math.isqrt(discriminant)
    if root * root != discriminant:
        continue

    numerator = root - 3 * d
    if numerator % 6 != 0:
        continue
    y = numerator // 6
    if y > 0:
        ans = (y + d, y)
        break

if ans is None:
    print(-1)
else:
    print(*ans)

