from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Directions in clockwise order: SE, SW, NW, NE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        size = n * m
        # N: longest valid alternating run without a turn.
        # T: longest run with at most one clockwise turn still available.
        N = [[bytearray(size) for _ in range(2)] for _ in range(4)]
        T = [[bytearray(size) for _ in range(2)] for _ in range(4)]

        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            for r in rows:
                for c in range(m):
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    for e, value in enumerate((2, 0)):
                        if grid[r][c] != value:
                            continue
                        N[d][e][i] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            N[d][e][i] += N[d][1 - e][nr * m + nc]

        for d, (dr, dc) in enumerate(dirs):
            tr, tc = dirs[(d + 1) % 4]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            for r in rows:
                for c in range(m):
                    i = r * m + c
                    for e, value in enumerate((2, 0)):
                        if grid[r][c] != value:
                            continue
                        opp = 1 - e
                        best = 0
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = T[d][opp][nr * m + nc]
                        nr, nc = r + tr, c + tc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = max(best, N[(d + 1) % 4][opp][nr * m + nc])
                        T[d][e][i] = 1 + best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        answer = max(answer, 1 + T[d][0][nr * m + nc])
        return answer

