from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def fact(x: int) -> int:
            r = 1
            for i in range(2, x + 1):
                r *= i
                if r >= k:
                    return k
            return r

        odds = (n + 1) // 2
        evens = n // 2
        total = fact(odds) * fact(evens)
        total = min(k, total * (2 if odds == evens else 1))
        if k > total:
            return []

        available = list(range(1, n + 1))
        result = []
        prev_parity = None

        while available:
            chosen = False
            odd_count = sum(y % 2 == 1 for y in available)
            for x in available:
                parity = x % 2
                if prev_parity is not None and parity == prev_parity:
                    continue

                rem_odd = odd_count - (parity == 1)
                rem_even = len(available) - odd_count - (parity == 0)
                remaining_length = len(available) - 1

                if remaining_length == 0:
                    ways = 1
                else:
                    required_parity = 1 - parity
                    required_slots = (remaining_length + (required_parity == 1)) // 2
                    other_slots = remaining_length - required_slots
                    if rem_odd != required_slots or rem_even != other_slots:
                        ways = 0
                    else:
                        ways = min(k, fact(rem_odd) * fact(rem_even))

                if k > ways:
                    k -= ways
                else:
                    result.append(x)
                    available.remove(x)
                    prev_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return result

