class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        weights = []
        for i in range(m):
            j = n - 1 - i
            w = pow(10, i, k)
            if j != i:
                w = (w + pow(10, j, k)) % k
            weights.append(w)

        # suffix[i][r] is true when the variables from i onward can
        # contribute residue r modulo k.
        suffix = [None] * (m + 1)
        suffix[m] = bytearray(k)
        suffix[m][0] = 1
        for i in range(m - 1, -1, -1):
            reachable = bytearray(k)
            w = weights[i]
            nxt = suffix[i + 1]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        reachable[(r + d * w) % k] = 1
            suffix[i] = reachable

        digits = []
        rem = 0
        for i, w in enumerate(weights):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (-rem - d * w) % k
                if suffix[i + 1][need]:
                    digits.append(str(d))
                    rem = (rem + d * w) % k
                    break

        half = ''.join(digits)
        return half + half[:n // 2][::-1]

