from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next strictly greater element for every index
        nxt = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                nxt[stack.pop()] = i
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        # A prefix-maximum block beginning at i extends through nxt[i] - 1.
        first_cost = [
            nums[i] * (nxt[i] - i) - (prefix[nxt[i]] - prefix[i])
            for i in range(n)
        ]
        levels = n.bit_length()
        jumps = [nxt]
        costs = [first_cost]
        for _ in range(1, levels):
            previous_jump = jumps[-1]
            previous_cost = costs[-1]
            current_jump = [n] * n
            current_cost = [0] * n
            for i in range(n):
                middle = previous_jump[i]
                if middle < n:
                    current_jump[i] = previous_jump[middle]
                    current_cost[i] = previous_cost[i] + previous_cost[middle]
                else:
                    current_cost[i] = previous_cost[i]
            jumps.append(current_jump)
            costs.append(current_cost)

        def subarray_cost(left: int, right: int) -> int:
            pos = left
            total = 0
            limit = right + 1
            for level in range(levels - 1, -1, -1):
                if pos < n and jumps[level][pos] <= limit:
                    total += costs[level][pos]
                    pos = jumps[level][pos]
            if pos <= right:
                total += nums[pos] * (right - pos + 1) - (prefix[right + 1] - prefix[pos])
            return total

        answer = 0
        for left in range(n):
            # Binary search the largest exclusive endpoint with affordable cost.
            low, high = left, n
            while low < high:
                mid = (low + high + 1) // 2
                if mid == left or subarray_cost(left, mid - 1) <= k:
                    low = mid
                else:
                    high = mid - 1
            answer += low - left
        return answer

