from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, _ in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        dp0 = [0] * n  # Parent edge not using a degree slot at this node
        dp1 = [0] * n  # Parent edge uses one degree slot at this node
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gain = w + dp1[v] - dp0[v]
                    if gain > 0:
                        gains.append(gain)
            gains.sort(reverse=True)
            dp0[u] = base + sum(gains[:k])
            dp1[u] = base + sum(gains[:max(0, k - 1)])

        return dp0[0]

