import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        component = [start]
        consistent = True
        for v in component:
            for w, z in adj[v]:
                expected = potential[v] ^ z
                if potential[w] == -1:
                    potential[w] = expected
                    component.append(w)
                elif potential[w] != expected:
                    consistent = False
        if not consistent:
            print(-1)
            return

        ones = [0] * 30
        for v in component:
            value = potential[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1
        root = 0
        for bit, count in enumerate(ones):
            if count > len(component) - count:
                root |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ root

    print(*answer)

if __name__ == '__main__':
    main()

