import sys

def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    p = 1
    ans = []
    for _ in range(t):
        n = int(data[p])
        a = data[p + 1]
        b = data[p + 2]
        p += 3
        xs = [i for i, c in enumerate(a) if c == 49]
        ys = [i for i, c in enumerate(b) if c == 49]
        if len(xs) < len(ys):
            ans.append('-1')
            continue

        def feasible(d):
            # Match each target to a distinct source in order.
            j = 0
            for y in ys:
                while j < len(xs) and xs[j] < y - d:
                    j += 1
                if j == len(xs) or xs[j] > y + d:
                    return False
                j += 1
            # Every source must be able to finish at some target.
            k = 0
            for x in xs:
                while k < len(ys) and ys[k] < x - d:
                    k += 1
                if k == len(ys) or ys[k] > x + d:
                    return False
            return True

        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        ans.append(str(lo))
    sys.stdout.write('\n'.join(ans))

if __name__ == '__main__':
    main()

