from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        post = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                post.append(v)
            else:
                stack.append((v, True))
                for c in reversed(children[v]):
                    stack.append((c, False))

        pos = [0] * n
        for i, v in enumerate(post):
            pos[v] = i
        size = [1] * n
        for v in post:
            if v != 0:
                size[parent[v]] += size[v]

        t = ''.join(s[v] for v in post)
        m = len(t)
        odd = [0] * m
        l = 0
        r = -1
        for i in range(m):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < m and t[i-k] == t[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * m
        l = 0
        r = -1
        for i in range(m):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < m and t[i-k-1] == t[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for v in range(n):
            length = size[v]
            left = pos[v] - length + 1
            if length % 2:
                center = (left + pos[v]) // 2
                ans[v] = odd[center] >= length // 2 + 1
            else:
                center = (left + pos[v] + 1) // 2
                ans[v] = even[center] >= length // 2
        return ans

