from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix sums at indices with the same remainder modulo k can
        # define subarrays whose lengths are divisible by k.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = None

        for end, value in enumerate(nums, 1):
            prefix += value
            remainder = end % k

            # Query before updating, ensuring the subarray is nonempty.
            if min_prefix[remainder] is not None:
                candidate = prefix - min_prefix[remainder]
                if best is None or candidate > best:
                    best = candidate

            if min_prefix[remainder] is None or prefix < min_prefix[remainder]:
                min_prefix[remainder] = prefix

        return best

