from math import gcd, lcm

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(arr: List[int]) -> int:
            if not arr:
                return 0
            common = multiple = arr[0]
            for x in arr[1:]:
                common = gcd(common, x)
                multiple = lcm(multiple, x)
            return common * multiple

        best = score(nums)
        for i in range(len(nums)):
            best = max(best, score(nums[:i] + nums[i + 1:]))
        return best

