from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        ans = 0
        for i in range(len(nums)):
            for j in range(i):
                a, b = str(nums[i]), str(nums[j])
                width = max(len(a), len(b))
                a, b = a.zfill(width), b.zfill(width)
                diff = [k for k in range(width) if a[k] != b[k]]
                if not diff:
                    ans += 1
                elif len(diff) == 2:
                    p, q = diff
                    if a[p] == b[q] and a[q] == b[p]:
                        ans += 1
        return ans

