from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)
        answer = None

        for outlier in nums:
            remaining = total - outlier
            if remaining % 2 != 0:
                continue

            sum_element = remaining // 2
            # The outlier and sum element need distinct indices.
            if counts[sum_element] - (sum_element == outlier) > 0:
                if answer is None or outlier > answer:
                    answer = outlier

        return answer

