class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10 ** len(str(n))
        low = limit // 10 if limit > 10 else 0

        prime = bytearray(b'\x01') * limit
        prime[0] = 0
        if limit > 1:
            prime[1] = 0
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = b'\x00' * (((limit - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        places = [10 ** i for i in range(len(str(n)))]
        dist = {n: n}
        pq = [(n, n)]

        while pq:
            cost, x = heapq.heappop(pq)
            if dist[x] != cost:
                continue
            if x == m:
                return cost

            for place in places:
                digit = (x // place) % 10
                for delta in (-1, 1):
                    if not 0 <= digit + delta <= 9:
                        continue
                    y = x + delta * place
                    if y < low or y >= limit or prime[y]:
                        continue
                    new_cost = cost + y
                    if new_cost < dist.get(y, float('inf')):
                        dist[y] = new_cost
                        heapq.heappush(pq, (new_cost, y))

        return -1

