from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        def zfunc(a):
            m = len(a)
            z = [0] * m
            l = r = 0
            for k in range(1, m):
                if k < r:
                    z[k] = min(r - k, z[k - l])
                while k + z[k] < m and a[z[k]] == a[k + z[k]]:
                    z[k] += 1
                if k + z[k] > r:
                    l, r = k, k + z[k]
            return z

        z = zfunc(nums)
        # nums1 is a prefix of nums2; for each valid i, count possible j.
        ans = sum(n - 2 * i for i in range(1, n) if z[i] >= i)

        # nums2 is a prefix of nums3. For each i and length d,
        # compare the two blocks starting at i and i+d.
        for i in range(1, n - 1):
            zi = zfunc(nums[i:])
            for d in range(1, (n - i) // 2 + 1):
                if zi[d] >= d:
                    ans += 1

        return ans

