        return

    longer, shorter = (s, t) if n > m else (t, s)
    i = j = skipped = 0
    while i < len(longer) and j < len(shorter):
        if longer[i] == shorter[j]:
            i += 1
            j += 1
        else:
            skipped += 1
            i += 1
            if skipped > k:
                break
    print('Yes' if skipped <= k else 'No')

