from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        removable = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            # Keep the character unused, delete it if allowed, or match it.
            ndp = dp.copy()
            for j, value in enumerate(dp):
                if value == neg:
                    continue
                if i in removable:
                    ndp[j] = max(ndp[j], value + 1)
                if j < m and ch == pattern[j]:
                    ndp[j + 1] = max(ndp[j + 1], value)
            dp = ndp

        return dp[m]

