from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        incoming = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            incoming[b].append((a, w))
            weights.add(w)

        vals = sorted(weights)

        def feasible(limit):
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in incoming[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        count += 1
                        stack.append(u)
            return count == n

        if not feasible(vals[-1]):
            return -1
        lo, hi = 0, len(vals) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(vals[mid]):
                hi = mid
            else:
                lo = mid + 1
        return vals[lo]

